	/** What a given argument position accepts. */
	enum ArgType {
		/** Any numeric literal (integer, decimal, float, double). */
		NUMERIC,
		/** An integer-typed literal only. */
		INTEGER,
		/** Any literal, used for its lexical form (patterns, locale tags). */
		PATTERN,
		/** Any RDF term; SPARQL ordering / equality applies. */
		ANY;

		boolean literalRequired() {
			return this != ANY;
		}

		boolean numeric() {
			return this == NUMERIC || this == INTEGER;
		}
	}

	static final class Spec {
		final Function function;
		final IRI constant;
		final int minArity;
		/** -1 for variadic functions. */
		final int maxArity;
		final ArgType[] types;
		final Value[] sample;
		final CoreDatatype.XSD resultType;

		Spec(Function function, IRI constant, int minArity, int maxArity, ArgType[] types, Value[] sample,
				CoreDatatype.XSD resultType) {
			this.function = function;
			this.constant = constant;
			this.minArity = minArity;
			this.maxArity = maxArity;
			this.types = types;
			this.sample = sample;
			this.resultType = resultType;
		}

		ArgType typeAt(int position) {
			return types[Math.min(position, types.length - 1)];
		}

		Value[] withArg(int position, Value replacement) {
			Value[] args = sample.clone();
			args[position] = replacement;
			return args;
		}

		@Override
		public String toString() {
			return function.getClass().getSimpleName();
		}
	}

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static Literal decimal(String v) {
		return VF.createLiteral(v, CoreDatatype.XSD.DECIMAL);
	}

	private static Spec unaryDouble(Function function, IRI constant) {
		return new Spec(function, constant, 1, 1, new ArgType[] { ArgType.NUMERIC },
				new Value[] { decimal("0.5") }, CoreDatatype.XSD.DOUBLE);
	}

	private static Spec binaryDouble(Function function, IRI constant) {
		return new Spec(function, constant, 2, 2, new ArgType[] { ArgType.NUMERIC, ArgType.NUMERIC },
				new Value[] { decimal("0.5"), integer(2) }, CoreDatatype.XSD.DOUBLE);
	}

	private static Spec bitwise(Function function, IRI constant, int arity) {
		ArgType[] types = new ArgType[arity];
		Arrays.fill(types, ArgType.INTEGER);
		Value[] sample = arity == 1 ? new Value[] { integer(12) } : new Value[] { integer(12), integer(3) };
		return new Spec(function, constant, arity, arity, types, sample, CoreDatatype.XSD.INTEGER);
	}

