	private static void assertError(Spec spec, String description, Value... args) {
		assertThatThrownBy(() -> spec.function.evaluate(VF, args)).as(spec + ": " + description)
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@ParameterizedTest
	@MethodSource("specs")
	void sampleArgumentsEvaluate(Spec spec) {
		Value result = spec.function.evaluate(VF, spec.sample);
		assertThat(result).as(spec.toString()).isInstanceOf(Literal.class);
		assertThat(((Literal) result).getCoreDatatype()).as(spec.toString()).isEqualTo(spec.resultType);
	}

	@ParameterizedTest
	@MethodSource("specs")
	void wrongArityIsAnError(Spec spec) {
		if (spec.minArity > 0) {
			assertError(spec, "zero arguments");
		}
		if (spec.minArity > 1) {
			assertError(spec, "one argument too few", Arrays.copyOf(spec.sample, spec.minArity - 1));
		}
		if (spec.maxArity >= 0) {
			Value[] tooMany = Arrays.copyOf(spec.sample, spec.sample.length + 1);
			tooMany[spec.sample.length] = spec.sample.length == 0 ? integer(1) : spec.sample[0];
			assertError(spec, "one argument too many", tooMany);
		}
	}

