	void malformedLexicalFormIsAnError(Spec spec) {
		for (int i = 0; i < spec.sample.length; i++) {
			if (spec.typeAt(i).numeric()) {
				assertError(spec, "abc^^xsd:integer argument " + i,
						spec.withArg(i, VF.createLiteral("abc", CoreDatatype.XSD.INTEGER)));
				assertError(spec, "1.5^^xsd:integer argument " + i,
						spec.withArg(i, VF.createLiteral("1.5", CoreDatatype.XSD.INTEGER)));
				assertError(spec, "abc^^xsd:double argument " + i,
						spec.withArg(i, VF.createLiteral("abc", CoreDatatype.XSD.DOUBLE)));
				assertError(spec, "1,5^^xsd:decimal argument " + i,
						spec.withArg(i, VF.createLiteral("1,5", CoreDatatype.XSD.DECIMAL)));
			}
		}
	}

