	@ParameterizedTest
	@MethodSource("specs")
	void resultLexicalFormIsCanonical(Spec spec) {
		Literal result = (Literal) spec.function.evaluate(VF, spec.sample);
		CoreDatatype.XSD datatype = (CoreDatatype.XSD) result.getCoreDatatype();
		assertThat(XMLDatatypeUtil.isValidValue(result.getLabel(), datatype)).as(spec + " " + result).isTrue();
		assertThat(result.getLanguage()).as(spec.toString()).isEmpty();
		if (datatype == CoreDatatype.XSD.DOUBLE) {
			// RDF4J's canonical double form is the value factory's (shortest round-trip, "INF"/"NaN" spellings)
			assertThat(result.getLabel()).isEqualTo(VF.createLiteral(result.doubleValue()).getLabel());
			assertThat(result.getLabel()).doesNotContain("Infinity");
		} else if (datatype == CoreDatatype.XSD.INTEGER) {
			assertThat(result.getLabel()).isEqualTo(result.integerValue().toString());
		} else if (datatype == CoreDatatype.XSD.DECIMAL) {
			assertThat(result.getLabel()).isEqualTo(result.decimalValue().toPlainString());
		}
	}

	@ParameterizedTest
	@MethodSource("specs")
	void repeatedEvaluationGivesIdenticalResults(Spec spec) {
		Value first = spec.function.evaluate(VF, spec.sample);
		Value second = spec.function.evaluate(VF, spec.sample);
		assertThat(second).as(spec.toString()).isEqualTo(first);
		Function fresh = FunctionRegistry.getInstance().get(spec.function.getURI()).orElseThrow();
		assertThat(fresh.evaluate(VF, spec.sample)).as(spec + " via registry").isEqualTo(first);
	}

	@ParameterizedTest
	@MethodSource("specs")
	void concurrentEvaluationGivesIdenticalResults(Spec spec) throws Exception {
		Value expected = spec.function.evaluate(VF, spec.sample);
		ExecutorService executor = Executors.newFixedThreadPool(8);
		try {
			List<Callable<List<Value>>> tasks = new ArrayList<>();
			for (int t = 0; t < 8; t++) {
				tasks.add(() -> {
					List<Value> results = new ArrayList<>();
					for (int i = 0; i < 200; i++) {
						results.add(spec.function.evaluate(VF, spec.sample));
					}
					return results;
				});
			}
			for (Future<List<Value>> future : executor.invokeAll(tasks)) {
				assertThat(future.get()).as(spec.toString()).allSatisfy(v -> assertThat(v).isEqualTo(expected));
			}
		} finally {
			executor.shutdownNow();
		}
	}

