	@Test
	void everyVocabularyConstantHasAFunction() throws IllegalAccessException {
		Set<String> uris = specs().stream().map(spec -> spec.function.getURI()).collect(Collectors.toSet());
		FunctionRegistry registry = FunctionRegistry.getInstance();
		for (Class<?> vocabulary : List.of(MATHF.class, BITF.class, MISCF.class)) {
			int constants = 0;
			for (Field field : vocabulary.getFields()) {
				if (Modifier.isStatic(field.getModifiers()) && IRI.class.isAssignableFrom(field.getType())) {
					String iri = ((IRI) field.get(null)).stringValue();
					assertThat(uris).as(vocabulary.getSimpleName() + "." + field.getName()).contains(iri);
					assertThat(registry.get(iri)).as(iri).isPresent();
					constants++;
				}
			}
			assertThat(constants).as(vocabulary.getSimpleName()).isPositive();
		}
	}

	@Test
	void xpathAliasesUseTheXPathMathNamespace() {
		for (Spec spec : specs()) {
			if (spec.constant == null) {
				assertThat(spec.function.getURI()).as(spec.toString()).startsWith(MATHF.XPATH_MATH_NAMESPACE);
			} else {
				assertThat(spec.function.getURI()).as(spec.toString()).doesNotStartWith(MATHF.XPATH_MATH_NAMESPACE);
			}
		}
	}

	private static List<String> serviceFileEntries() throws IOException {
		List<String> entries = new ArrayList<>();
		Enumeration<URL> resources = Function.class.getClassLoader().getResources(SERVICE_FILE);
		for (URL url : Collections.list(resources)) {
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					int comment = line.indexOf('#');
					String entry = (comment >= 0 ? line.substring(0, comment) : line).trim();
					if (!entry.isEmpty()) {
						entries.add(entry);
					}
				}
			}
		}
		return entries;
	}
